import { describe, it } from "vitest";

// Premiums are observed as final quote results. Unless stated otherwise the
// customer has 0 years with MHPCO and the quote is the scenario's first, so
// the 10 % first-insurance surcharge and the 5 G fee apply.
// Rejections are observed at the CLI: non-zero exit status, an error
// description on stderr and no results on stdout.
describe("MHPCO claim office", () => {
  it.todo("quotes an empty item list at 5 G (processing fee only)");
  it.todo("quotes a plain sword at 115 G (100 base + 10 first insurance + 5 fee)");
  it.todo("quotes a plain amulet at 71 G (60 base + 6 first insurance + 5 fee)");
  it.todo("quotes a plain staff at 93 G (80 base + 8 first insurance + 5 fee)");
  it.todo("quotes a plain potion at 49 G (40 base + 4 first insurance + 5 fee)");
  it.todo("quotes 2 runes at 60 G (50 base, no block)");
  it.todo("quotes 3 runes at 71 G (block base premium 60)");
  it.todo("rounds a premium of 197.5 G up to 198 G (7 runes, base 175, no block)");
  it.todo("quotes 2 runes + 1 moonstone at 88 G (base 75: different types form no block; 87.5 rounded up)");
  it.todo("quotes a newcomer's cursed steel sword (enchantment 3) at 165 G (100 + 50 curse + 10 first + 5 fee)");
  it.todo("applies the curse surcharge only to the cursed item: cursed sword + plain amulet at 231 G (160 base + 50 curse + 16 first + 5 fee)");
  it.todo("adds the high-enchantment surcharge at exactly enchantment 5: sword at 145 G (100 + 30 + 10 + 5 fee)");
  it.todo("grants the loyalty discount at exactly 2 years: plain sword at 95 G (100 − 20 + 10 + 5 fee)");
  it.todo("grants the 15 % follow-up discount on the customer's second quote: plain sword at 100 G (100 + 10 − 15 + 5 fee)");
  it.todo("pays 400 G for 500 G damage to a regular steel sword (enchantment 3), remaining cap 1600 G");
  it.todo("uses the amulet's 600 G insurance value: 200 G amulet damage pays 100 G, remaining cap 1100 G");
  it.todo("uses the staff's 800 G insurance value: 300 G staff damage pays 200 G, remaining cap 1400 G");
  it.todo("uses the potion's 400 G insurance value: 300 G potion damage pays 200 G, remaining cap 600 G");
  it.todo("uses a rune's 250 G insurance value: 200 G rune damage pays 100 G, remaining cap 400 G");
  it.todo("reimburses 50 % for enchantment ≥ 8: steel sword enchantment 9, damage 1000 G pays 400 G");
  it.todo("rounds a payout of 350.5 G down to 350 G (steel sword enchantment 9, damage 901 G)");
  it.todo("applies the deductible per damaged item: sword 500 G + amulet 300 G pays 600 G, remaining cap 2600 G");
  it.todo("limits successive claims to the remaining cap: two 1500 G sword claims pay 1400 G (cap left 600 G) then 600 G (cap left 0 G)");
  it.todo("CLI writes the schema example results to stdout: premium 59 G, payout 100 G, remaining cap 1100 G");
  it.todo("CLI rejects a quote with unknown item type 'broomstick': non-zero exit, stderr message, empty stdout");
  it.todo("CLI rejects a claim damaging an amulet when only a sword is insured: non-zero exit, stderr message, empty stdout");
  it.todo("CLI rejects a claim with two sword damages when only one sword is insured: non-zero exit, stderr message, empty stdout");
  it.todo("CLI rejects a claim with a damage amount of -200: non-zero exit, stderr message, empty stdout");

  describe("verification", () => {
    it.todo("quotes 4 runes at 115 G (base 100: block requires exactly 3)");
    it.todo("quotes 3 runes + 3 moonstones at 137 G (base 120: two separate blocks)");
    it.todo("quotes a single moonstone at 33 G (base 25, 32.5 rounded up)");
    it.todo("adds no high-enchantment surcharge at enchantment 4: sword at 115 G");
    it.todo("adds both surcharges for a cursed sword at enchantment 5: 195 G");
    it.todo("adds only the curse surcharge for a cursed sword at enchantment 4: 165 G");
    it.todo("grants no loyalty discount below 2 years (1 year): plain sword at 115 G");
    it.todo("quotes a long-standing customer's second contract, cursed sword enchantment 7, at 160 G");
    it.todo("grants the follow-up discount on every later contract: third quote plain sword at 100 G");
    it.todo("uses a moonstone's 250 G insurance value: 200 G moonstone damage pays 100 G, remaining cap 400 G");
    it.todo("pays 400 G for a dragon-material sword at exactly enchantment 8 with damage 1000 G");
    it.todo("lets the 50 % rule win over dragon material: dragon sword enchantment 9, damage 1000 G pays 400 G");
    it.todo("fully reimburses dragon material below enchantment 8: dragon sword enchantment 5, damage 800 G pays 700 G");
    it.todo("treats two sword damages on a two-sword policy separately: 500 G + 500 G pays 800 G, remaining cap 3200 G (cap 4000)");
    it.todo("bases the cap on unmodified insurance value: cursed sword, 500 G damage pays 400 G, remaining cap 1600 G (cap 2000)");
    it.todo("keeps the block out of the insurance sum: sword + 3 runes, 200 G rune damage pays 100 G, remaining cap 3400 G (cap 3500)");
    it.todo("keeps separate caps per policy: a claim on step 1's policy leaves step 0's policy untouched");
    it.todo("CLI rejects a claim damaging an unknown item type: non-zero exit, stderr message, empty stdout");
  });
});

