export type InsuredItem = {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
};

export type QuoteStep = { op: "quote"; items: InsuredItem[] };

export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
};

export type QuoteResult = { premium: number };

const PROCESSING_FEE = 5;
const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};
const COMPONENT_BASE_PREMIUM = 25;
const BUILDING_BLOCK_SIZE = 3;
const BUILDING_BLOCK_BASE_PREMIUM = 60;

function componentsBasePremium(count: number): number {
  return count === BUILDING_BLOCK_SIZE
    ? BUILDING_BLOCK_BASE_PREMIUM
    : count * COMPONENT_BASE_PREMIUM;
}
const PERCENT = 100;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;

function isComponent(item: InsuredItem): boolean {
  return item.type === "rune";
}

function policyBasePremium(items: InsuredItem[]): number {
  const runes = items.filter(isComponent);
  const mainItems = items.filter((item) => !isComponent(item));
  return (
    mainItems.reduce((sum, item) => sum + MAIN_ITEM_BASE_PREMIUMS[item.type], 0) +
    componentsBasePremium(runes.length)
  );
}

function quotePremium(items: InsuredItem[]): number {
  const basePremium = policyBasePremium(items);
  const firstInsuranceSurcharge =
    (basePremium * FIRST_INSURANCE_SURCHARGE_PERCENT) / PERCENT;
  return basePremium + firstInsuranceSurcharge + PROCESSING_FEE;
}

export function runScenario(scenario: Scenario): { results: QuoteResult[] } {
  return {
    results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })),
  };
}

