import { type ClaimResult, type Damage, settleClaim } from "./claim.js";
import { type Customer, type InsuredItem, quotePremium } from "./premium.js";

export type QuoteStep = { op: "quote"; items: InsuredItem[] };

export type ClaimStep = {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
};

export type Scenario = {
  customer: Customer;
  steps: (QuoteStep | ClaimStep)[];
};

export type QuoteResult = { premium: number };

export function runScenario(scenario: Scenario): { results: (QuoteResult | ClaimResult)[] } {
  const { customer, steps } = scenario;
  return {
    results: steps.map((step, index) => {
      if (step.op === "claim") {
        const policy = steps[step.policy] as QuoteStep;
        return settleClaim(policy.items, step.incident.damages);
      }
      return { premium: quotePremium(customer, step.items, index > 0) };
    }),
  };
}
